$_MODULE['<{lggooglereviews}prestashop>help_21b295c24b7e059595f2393eee97eb8e'] = 'U kunt selecteren welke artikelen u wilt weergeven en hoe u dat wilt doen in het openbare gedeelte van uw winkel. Ga hiervoor naar het tabblad \"Presentatie\" van je zaak:';
$_MODULE['<{lggooglereviews}prestashop>help_3612879708f67ddbaffef6b85b8a7721'] = 'In het veld \"Te tonen beoordelingen\" kunt u het aantal blokken kiezen dat tegelijkertijd in de schuifbalk moet worden getoond.';
$_MODULE['<{lggooglereviews}prestashop>help_a8a22f09149459a347b30e8005ab34f4'] = '\"Rich Snippets\" zijn een set tags die niet zichtbaar zijn voor uw klanten, maar door zoekmachines worden gebruikt om informatie uit hun meningen te verzamelen. Als u het zoekmachines gemakkelijker wilt maken om deze informatie te verkrijgen, vinkt u \"Ja\" aan.';
$_MODULE['<{lggooglereviews}prestashop>help_dee2ff8dd3e1feec8bb332b79163a1a4'] = '\"Toon header\" zal aan het begin van het blok een header bevatten waarin u uw bedrijfsgegevens kunt tonen zoals: de naam, de afbeelding, de beoordelingen en de links naar uw profiel in Google Places.';
$_MODULE['<{lggooglereviews}prestashop>help_554d5ff6ac027319ca16bf76c83c6095'] = '\"Toon headerafbeelding\" bevat de afbeelding die bij uw bedrijf hoort als u deze hebt geüpload, en zo niet, het standaardpictogram dat u hebt gedefinieerd in Google Mijn Bedrijf.';
$_MODULE['<{lggooglereviews}prestashop>help_bc1b4b599ba23e1aaeda1e0d4de99c3b'] = '\"Link naar de Google My Business-pagina van uw bedrijf tonen\" toont een link naar uw bedrijfsprofiel op Google My Business.';
$_MODULE['<{lggooglereviews}prestashop>help_ee27a2fa1a14965f274765a67e5a8924'] = '\"Toon link naar [Bekijk alle beoordelingen]\" toont een link waar uw klanten uw volledige lijst met beoordelingen op Google Mijn Bedrijf kunnen openen.';
$_MODULE['<{lggooglereviews}prestashop>help_559358899352d23a924ba8782fd364dc'] = '\"Toon link naar [Voeg recensie toe]\" toont een link om uw klanten uit te nodigen een recensie over uw bedrijf achter te laten.';
$_MODULE['<{lggooglereviews}prestashop>help_1ef8624b78f3fd5b154773974b2f2dac'] = 'Als je de vorige optie hebt gekozen, moet je de url van de uitnodiging meesturen. In de sectie \"Beoordelingen aanvragen\" van de help leggen we uit hoe je die verkrijgt';
$_MODULE['<{lggooglereviews}prestashop>help_85cd03234f067e40d64fe6c28797fa67'] = 'Geef aan of u het bericht \"Powered by Google\" wilt weergeven.';
$_MODULE['<{lggooglereviews}prestashop>help_1628dd7f0d2519316c69e4e7700b9b2f'] = 'Geef aan of u uw score wilt weergeven op Google my Business';
$_MODULE['<{lggooglereviews}prestashop>help_3203e573a77f0fd7c5948c3d846abc52'] = 'Geef aan of u het aantal verkregen beoordelingen in Google my Business wilt tonen';
$_MODULE['<{lggooglereviews}prestashop>help_bfd47e79bf08ab639511bf993139b22e'] = 'Als u de lijst met de laatst ontvangen beoordelingen wilt tonen, selecteert u de optie';
$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Geef aan of je een link wilt tonen naar het profiel van gebruikers die hun beoordelingen hebben achtergelaten';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Uw bedrijfsgegevens herzien';
$_MODULE['<{lggooglereviews}prestashop>help_367c548945a796b5e52169e33b27202b'] = 'In het tabblad \"Statistieken\" ziet u een statistisch overzicht van uw bedrijfsgegevens in Google Mijn Bedrijf.';
$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Om de API\'s van Google Maps en Places te gebruiken, moet u de toepassing registreren en een API-sleutel krijgen. Waarschijnlijk weet u dat al, maar wij leggen uit hoe u deze sleutel verkrijgt als u dat niet weet.';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'Hoe maakt u uw Google Maps API KEY aan?';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Volg de onderstaande instructies om een API KEY aan te maken.';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'U moet inloggen met uw gmail-account of een nieuw gmail-account aanmaken dat u aan uw project wilt koppelen.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Eenmaal ingelogd moet u naar de Google Cloud Platform console gaan:';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'In het linkermenu gaat u naar het onderdeel APIS en Diensten.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Schrijf de naam van het project en klik op de knop \"CREËREN\".';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Daarna klikken we op de knop \"ENABLE APIS AND SERVICES\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'Selecteer in dit geval \"API PLACES\".';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Klik op de \"ENABLE\" knop.';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Zodra de API is aangemaakt, in het tabblad \"Credentials\". Klik daar op de link \"Credentials in API\'s en services\".';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Kopieer de API Key die op het scherm verschijnt, want die hebben we later nodig.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'U zult zien dat in datzelfde pop-upvenster de optie \"Wachtwoord beperken\" staat. Klik op die link als u wilt dat die sleutel bijvoorbeeld alleen in een bepaald domein wordt gebruikt.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Zodra u het wachtwoord hebt beperkt, moeten wij, als u dat wilt, de factureringsgegevens invoeren omdat wij deze API anders maar één keer per dag mogen aanroepen. Dit betekent niet dat ons iets in rekening wordt gebracht, want Google biedt u deze dienst gratis aan voor een groot aantal aanroepen naar de API, een aantal waarvoor een mkb-bedrijf normaal gesproken niet hoeft te betalen. Als u het aantal weergaven dat Google u gratis geeft, overschrijdt, is het waarschijnlijk dat het heel, heel goed gaat met het bedrijf en dat u er geen probleem mee moet hebben om hier wat in te investeren. Zelfs als u er niet overheen komt, vraagt Google u om uw factuurgegevens voor het geval dat op een gegeven moment gebeurt. Aan de andere kant, voor uw gemoedsrust, vertel ik u dat Google u toestaat een limiet te zetten op het aantal aanroepen naar zijn API per maand. U kunt dus het aantal gratis gesprekken per maand beperken en u zult dus nooit in rekening worden gebracht; de meningen worden gewoon stopgezet als u dat aantal overschrijdt.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'Hoe voert u de factureringsgegevens in?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Volg de onderstaande instructies om uw factuurgegevens in te voeren.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'Als we in de Google Cloud Platform-console klikken op het menupictogram met 3 horizontale lijnen, dat helemaal links staat, verschijnt het navigatiemenu. Daar moeten we klikken op het item \"Billing\".';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'We klikken op de knop \"Factuurrekeningen beheren\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'We klikken op de knop \"Factuuraccount toevoegen\" en volgen de door Google aangegeven stappen, waarbij we de gevraagde informatie invoeren.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Selecteer het Google-betalingsprofiel dat aan deze factureringsaccount zal worden gekoppeld. U kunt een bestaand profiel selecteren of een nieuw profiel aanmaken.';
